import pytest
import torch

from . import base, consts

# Shapes covering 2D, 3D and 4D, mirroring benchmark/test_transpose.py. The
# shared core_shapes.yaml fallback includes rank-1 entries, but transpose_ is a
# no-op below rank 2, so the shapes are pinned here to keep every case
# measuring an actual size/stride swap.
TRANSPOSE_SHAPES = [
    (64, 64),
    (256, 512),
    (1024, 1024),
    (4096, 4096),
    (64, 512, 512),
    (128, 256, 64),
    (8, 16, 32, 64),
]


class Transpose_Benchmark(base.Benchmark):
    """Benchmark for aten::transpose_ (in-place metadata-only swap)."""

    DEFAULT_SHAPE_DESC = "input shape"

    def set_shapes(self, shape_file_path=None):
        self.shapes = TRANSPOSE_SHAPES

    def get_input_iter(self, cur_dtype):
        for shape in self.shapes:
            inp = base.generate_tensor_input(shape, cur_dtype, self.device)
            # Swap the first and last dimensions of every operand. Both dims
            # stay within the operand's rank, so repeated timing iterations
            # just toggle the metadata between two valid states.
            yield inp, 0, inp.dim() - 1


@pytest.mark.transpose_
def test_transpose_():
    bench = Transpose_Benchmark(
        op_name="transpose_",
        torch_op=torch.ops.aten.transpose_,
        dtypes=consts.FLOAT_DTYPES,
    )
    bench.run()
